import java.util.EnumMap;
import java.util.Map;
import java.util.OptionalLong;
import java.util.function.LongSupplier;

public class Solution {
    enum Estado { CLOSED, LISTEN, SYN_SENT, SYN_RCVD, ESTABLISHED, FIN_WAIT_1, FIN_WAIT_2, CLOSE_WAIT, CLOSING, LAST_ACK, TIME_WAIT }

    enum Evento { ABERTURA_PASSIVA, ABERTURA_ATIVA, FECHAR, RECEBE_SYN, RECEBE_SYN_ACK, RECEBE_ACK, RECEBE_FIN, RECEBE_FIN_ACK, RECEBE_RST, TIMEOUT_CONEXAO }

    static final class ConexaoTcp {
        private static final Map<Estado, Map<Evento, Estado>> TABELA = new EnumMap<>(Estado.class);

        private static void t(Estado de, Evento evento, Estado para) {
            TABELA.computeIfAbsent(de, k -> new EnumMap<>(Evento.class)).put(evento, para);
        }

        static {
            t(Estado.CLOSED, Evento.ABERTURA_PASSIVA, Estado.LISTEN);
            t(Estado.CLOSED, Evento.ABERTURA_ATIVA, Estado.SYN_SENT);

            t(Estado.LISTEN, Evento.RECEBE_SYN, Estado.SYN_RCVD);
            t(Estado.LISTEN, Evento.FECHAR, Estado.CLOSED);

            t(Estado.SYN_SENT, Evento.RECEBE_SYN_ACK, Estado.ESTABLISHED);
            t(Estado.SYN_SENT, Evento.FECHAR, Estado.CLOSED);
            t(Estado.SYN_SENT, Evento.RECEBE_RST, Estado.CLOSED);
            t(Estado.SYN_SENT, Evento.TIMEOUT_CONEXAO, Estado.CLOSED);

            t(Estado.SYN_RCVD, Evento.RECEBE_ACK, Estado.ESTABLISHED);
            t(Estado.SYN_RCVD, Evento.FECHAR, Estado.FIN_WAIT_1);
            t(Estado.SYN_RCVD, Evento.RECEBE_RST, Estado.LISTEN);
            t(Estado.SYN_RCVD, Evento.TIMEOUT_CONEXAO, Estado.LISTEN);

            t(Estado.ESTABLISHED, Evento.FECHAR, Estado.FIN_WAIT_1);
            t(Estado.ESTABLISHED, Evento.RECEBE_FIN, Estado.CLOSE_WAIT);
            t(Estado.ESTABLISHED, Evento.RECEBE_RST, Estado.CLOSED);

            t(Estado.FIN_WAIT_1, Evento.RECEBE_ACK, Estado.FIN_WAIT_2);
            t(Estado.FIN_WAIT_1, Evento.RECEBE_FIN, Estado.CLOSING);
            t(Estado.FIN_WAIT_1, Evento.RECEBE_FIN_ACK, Estado.TIME_WAIT);
            t(Estado.FIN_WAIT_1, Evento.RECEBE_RST, Estado.CLOSED);

            t(Estado.FIN_WAIT_2, Evento.RECEBE_FIN, Estado.TIME_WAIT);
            t(Estado.FIN_WAIT_2, Evento.RECEBE_RST, Estado.CLOSED);

            t(Estado.CLOSE_WAIT, Evento.FECHAR, Estado.LAST_ACK);
            t(Estado.CLOSE_WAIT, Evento.RECEBE_RST, Estado.CLOSED);

            t(Estado.CLOSING, Evento.RECEBE_ACK, Estado.TIME_WAIT);
            t(Estado.CLOSING, Evento.RECEBE_RST, Estado.CLOSED);

            t(Estado.LAST_ACK, Evento.RECEBE_ACK, Estado.CLOSED);
            t(Estado.LAST_ACK, Evento.RECEBE_RST, Estado.CLOSED);

            // TIME_WAIT: RECEBE_FIN (FIN retransmitido) reinicia o tempo; RECEBE_RST é ignorado.
            t(Estado.TIME_WAIT, Evento.RECEBE_FIN, Estado.TIME_WAIT);
            t(Estado.TIME_WAIT, Evento.RECEBE_RST, Estado.TIME_WAIT);
        }

        private final long doisMsl;
        private final LongSupplier relogio;
        private Estado estado = Estado.CLOSED;
        private long expiraEm = -1;

        ConexaoTcp(long mslMs, LongSupplier relogio) {
            if (mslMs <= 0) throw new IllegalArgumentException("msl precisa ser positivo");
            if (relogio == null) throw new IllegalArgumentException("relógio nulo");
            this.doisMsl = 2 * mslMs;
            this.relogio = relogio;
        }

        Estado estado() {
            expirarTimeWait();
            return estado;
        }

        boolean aceita(Evento evento) {
            if (evento == null) throw new IllegalArgumentException("evento nulo");
            expirarTimeWait();
            return TABELA.getOrDefault(estado, Map.of()).containsKey(evento);
        }

        Estado tratar(Evento evento) {
            if (!aceita(evento)) throw new IllegalStateException(evento + " não é válido em " + estado);
            Estado destino = TABELA.get(estado).get(evento);
            if (estado == Estado.TIME_WAIT) {
                if (evento == Evento.RECEBE_FIN) expiraEm = relogio.getAsLong() + doisMsl;   // reinicia o 2×MSL
                return estado;
            }
            estado = destino;
            if (estado == Estado.TIME_WAIT) expiraEm = relogio.getAsLong() + doisMsl;
            return estado;
        }

        OptionalLong expiraTimeWaitEm() {
            expirarTimeWait();
            return estado == Estado.TIME_WAIT ? OptionalLong.of(expiraEm) : OptionalLong.empty();
        }

        private void expirarTimeWait() {
            if (estado == Estado.TIME_WAIT && relogio.getAsLong() >= expiraEm) {
                estado = Estado.CLOSED;
                expiraEm = -1;
            }
        }
    }
}

