import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.OptionalLong;
import java.util.function.LongSupplier;

class SolutionTest {
    static final Solution.Estado CLOSED = Solution.Estado.CLOSED;
    static final Solution.Estado LISTEN = Solution.Estado.LISTEN;
    static final Solution.Estado SYN_SENT = Solution.Estado.SYN_SENT;
    static final Solution.Estado SYN_RCVD = Solution.Estado.SYN_RCVD;
    static final Solution.Estado ESTABLISHED = Solution.Estado.ESTABLISHED;
    static final Solution.Estado FIN_WAIT_1 = Solution.Estado.FIN_WAIT_1;
    static final Solution.Estado FIN_WAIT_2 = Solution.Estado.FIN_WAIT_2;
    static final Solution.Estado CLOSE_WAIT = Solution.Estado.CLOSE_WAIT;
    static final Solution.Estado CLOSING = Solution.Estado.CLOSING;
    static final Solution.Estado LAST_ACK = Solution.Estado.LAST_ACK;
    static final Solution.Estado TIME_WAIT = Solution.Estado.TIME_WAIT;
    static final Solution.Evento ABERTURA_PASSIVA = Solution.Evento.ABERTURA_PASSIVA;
    static final Solution.Evento ABERTURA_ATIVA = Solution.Evento.ABERTURA_ATIVA;
    static final Solution.Evento FECHAR = Solution.Evento.FECHAR;
    static final Solution.Evento RECEBE_SYN = Solution.Evento.RECEBE_SYN;
    static final Solution.Evento RECEBE_SYN_ACK = Solution.Evento.RECEBE_SYN_ACK;
    static final Solution.Evento RECEBE_ACK = Solution.Evento.RECEBE_ACK;
    static final Solution.Evento RECEBE_FIN = Solution.Evento.RECEBE_FIN;
    static final Solution.Evento RECEBE_FIN_ACK = Solution.Evento.RECEBE_FIN_ACK;
    static final Solution.Evento RECEBE_RST = Solution.Evento.RECEBE_RST;
    static final Solution.Evento TIMEOUT_CONEXAO = Solution.Evento.TIMEOUT_CONEXAO;

    static final class Relogio implements LongSupplier {
        long agora = 0;
        @Override public long getAsLong() { return agora; }
        Relogio em(long t) { agora = t; return this; }
    }

    static final long MSL = 30_000;

    static Solution.ConexaoTcp nova(Relogio t) { return new Solution.ConexaoTcp(MSL, t); }

    static void aplicar(Solution.ConexaoTcp c, Solution.Evento... eventos) {
        for (Solution.Evento e : eventos) c.tratar(e);
    }

    /** Caminho mais curto de CLOSED até cada estado. */
    static Solution.Evento[] caminho(Solution.Estado alvo) {
        return switch (alvo) {
            case CLOSED -> new Solution.Evento[] {};
            case LISTEN -> new Solution.Evento[] {ABERTURA_PASSIVA};
            case SYN_SENT -> new Solution.Evento[] {ABERTURA_ATIVA};
            case SYN_RCVD -> new Solution.Evento[] {ABERTURA_PASSIVA, RECEBE_SYN};
            case ESTABLISHED -> new Solution.Evento[] {ABERTURA_ATIVA, RECEBE_SYN_ACK};
            case FIN_WAIT_1 -> new Solution.Evento[] {ABERTURA_ATIVA, RECEBE_SYN_ACK, FECHAR};
            case FIN_WAIT_2 -> new Solution.Evento[] {ABERTURA_ATIVA, RECEBE_SYN_ACK, FECHAR, RECEBE_ACK};
            case CLOSE_WAIT -> new Solution.Evento[] {ABERTURA_ATIVA, RECEBE_SYN_ACK, RECEBE_FIN};
            case CLOSING -> new Solution.Evento[] {ABERTURA_ATIVA, RECEBE_SYN_ACK, FECHAR, RECEBE_FIN};
            case LAST_ACK -> new Solution.Evento[] {ABERTURA_ATIVA, RECEBE_SYN_ACK, RECEBE_FIN, FECHAR};
            case TIME_WAIT -> new Solution.Evento[] {ABERTURA_ATIVA, RECEBE_SYN_ACK, FECHAR, RECEBE_FIN_ACK};
        };
    }

    static Solution.ConexaoTcp em(Solution.Estado alvo, Relogio t) {
        Solution.ConexaoTcp c = nova(t);
        aplicar(c, caminho(alvo));
        assertEquals(alvo, c.estado(), "o caminho de teste deveria levar a " + alvo);
        return c;
    }

    // ---------- caminhos felizes ----------

    @Test void comecaFechada() {
        Solution.ConexaoTcp c = nova(new Relogio());
        assertEquals(CLOSED, c.estado());
        assertEquals(OptionalLong.empty(), c.expiraTimeWaitEm());
    }

    @Test void aberturaAtivaDoCliente() {
        Solution.ConexaoTcp c = nova(new Relogio());
        assertEquals(SYN_SENT, c.tratar(ABERTURA_ATIVA));
        assertEquals(ESTABLISHED, c.tratar(RECEBE_SYN_ACK));
    }

    @Test void aberturaPassivaDoServidor() {
        Solution.ConexaoTcp c = nova(new Relogio());
        assertEquals(LISTEN, c.tratar(ABERTURA_PASSIVA));
        assertEquals(SYN_RCVD, c.tratar(RECEBE_SYN));
        assertEquals(ESTABLISHED, c.tratar(RECEBE_ACK));
    }

    @Test void fechamentoAtivoPassaPorTimeWaitEVoltaAClosed() {
        Relogio t = new Relogio();
        Solution.ConexaoTcp c = em(ESTABLISHED, t);
        assertEquals(FIN_WAIT_1, c.tratar(FECHAR));
        assertEquals(FIN_WAIT_2, c.tratar(RECEBE_ACK));
        t.em(1_000);
        assertEquals(TIME_WAIT, c.tratar(RECEBE_FIN));
        assertEquals(OptionalLong.of(1_000 + 2 * MSL), c.expiraTimeWaitEm());
        t.em(1_000 + 2 * MSL - 1);
        assertEquals(TIME_WAIT, c.estado());
        t.em(1_000 + 2 * MSL);
        assertEquals(CLOSED, c.estado(), "no instante exato 2×MSL o TIME_WAIT já expirou");
        assertEquals(OptionalLong.empty(), c.expiraTimeWaitEm());
    }

    @Test void fechamentoPassivoPassaPorCloseWaitELastAck() {
        Solution.ConexaoTcp c = em(ESTABLISHED, new Relogio());
        assertEquals(CLOSE_WAIT, c.tratar(RECEBE_FIN));
        assertEquals(LAST_ACK, c.tratar(FECHAR));
        assertEquals(CLOSED, c.tratar(RECEBE_ACK));
    }

    @Test void finQueTambemConfirmaOnossoFinVaiDireitoParaTimeWait() {
        Solution.ConexaoTcp c = em(FIN_WAIT_1, new Relogio());
        assertEquals(TIME_WAIT, c.tratar(RECEBE_FIN_ACK));
    }

    @Test void fechamentoSimultaneoPassaPorClosing() {
        Solution.ConexaoTcp c = em(FIN_WAIT_1, new Relogio());
        assertEquals(CLOSING, c.tratar(RECEBE_FIN));
        assertEquals(TIME_WAIT, c.tratar(RECEBE_ACK));
    }

    @Test void podeReabrirDepoisDeFechar() {
        Relogio t = new Relogio();
        Solution.ConexaoTcp c = em(TIME_WAIT, t);
        t.em(2 * MSL);
        assertEquals(SYN_SENT, c.tratar(ABERTURA_ATIVA));
    }

    // ---------- RST, timeouts e fechamentos antecipados ----------

    @Test void rstDerrubaAConexaoNosEstadosEmQueEleValeParaClosed() {
        for (Solution.Estado e : List.of(SYN_SENT, ESTABLISHED, FIN_WAIT_1, FIN_WAIT_2, CLOSE_WAIT, CLOSING, LAST_ACK)) {
            Solution.ConexaoTcp c = em(e, new Relogio());
            assertEquals(CLOSED, c.tratar(RECEBE_RST), "RST em " + e);
        }
    }

    @Test void rstEmSynRcvdVoltaAoListen() {
        Solution.ConexaoTcp c = em(SYN_RCVD, new Relogio());
        assertEquals(LISTEN, c.tratar(RECEBE_RST));
    }

    @Test void timeoutDeConexao() {
        assertEquals(CLOSED, em(SYN_SENT, new Relogio()).tratar(TIMEOUT_CONEXAO));
        assertEquals(LISTEN, em(SYN_RCVD, new Relogio()).tratar(TIMEOUT_CONEXAO));
        assertFalse(em(ESTABLISHED, new Relogio()).aceita(TIMEOUT_CONEXAO));
    }

    @Test void fecharAntesDeEstabelecer() {
        assertEquals(CLOSED, em(LISTEN, new Relogio()).tratar(FECHAR));
        assertEquals(CLOSED, em(SYN_SENT, new Relogio()).tratar(FECHAR));
        assertEquals(FIN_WAIT_1, em(SYN_RCVD, new Relogio()).tratar(FECHAR));
    }

    // ---------- TIME_WAIT ----------

    @Test void finRetransmitidoReiniciaOTimeWait() {
        Relogio t = new Relogio();
        Solution.ConexaoTcp c = em(FIN_WAIT_2, t);
        t.em(100);
        c.tratar(RECEBE_FIN);
        assertEquals(OptionalLong.of(100 + 2 * MSL), c.expiraTimeWaitEm());
        t.em(40_000);
        assertEquals(TIME_WAIT, c.tratar(RECEBE_FIN));
        assertEquals(OptionalLong.of(40_000 + 2 * MSL), c.expiraTimeWaitEm(), "o 2×MSL recomeçou");
        t.em(100 + 2 * MSL);
        assertEquals(TIME_WAIT, c.estado(), "o prazo antigo já não vale");
    }

    @Test void rstEmTimeWaitEIgnoradoENaoMudaOTempo() {
        Relogio t = new Relogio();
        Solution.ConexaoTcp c = em(TIME_WAIT, t);
        OptionalLong antes = c.expiraTimeWaitEm();
        t.em(5_000);
        assertEquals(TIME_WAIT, c.tratar(RECEBE_RST));
        assertEquals(antes, c.expiraTimeWaitEm());
    }

    @Test void eventoDepoisDeExpirarOTimeWaitValeParaClosed() {
        Relogio t = new Relogio();
        Solution.ConexaoTcp c = em(TIME_WAIT, t);
        t.em(2 * MSL);
        assertFalse(c.aceita(RECEBE_FIN), "CLOSED não aceita FIN");
        assertThrows(IllegalStateException.class, () -> c.tratar(RECEBE_FIN));
        assertEquals(CLOSED, c.estado());
    }

    // ---------- transições inválidas ----------

    @Test void eventoInvalidoLancaEMantemOEstado() {
        Solution.ConexaoTcp c = em(ESTABLISHED, new Relogio());
        assertThrows(IllegalStateException.class, () -> c.tratar(RECEBE_SYN_ACK));
        assertThrows(IllegalStateException.class, () -> c.tratar(ABERTURA_ATIVA));
        assertEquals(ESTABLISHED, c.estado());
        assertEquals(FIN_WAIT_1, c.tratar(FECHAR), "e a máquina continua utilizável");
    }

    @Test void exemplosDeInvalidos() {
        assertThrows(IllegalStateException.class, () -> nova(new Relogio()).tratar(FECHAR));
        assertThrows(IllegalStateException.class, () -> nova(new Relogio()).tratar(RECEBE_SYN));
        assertThrows(IllegalStateException.class, () -> em(CLOSE_WAIT, new Relogio()).tratar(RECEBE_FIN));
        assertThrows(IllegalStateException.class, () -> em(FIN_WAIT_2, new Relogio()).tratar(FECHAR));
        assertThrows(IllegalStateException.class, () -> em(LAST_ACK, new Relogio()).tratar(FECHAR));
        assertThrows(IllegalStateException.class, () -> em(SYN_SENT, new Relogio()).tratar(RECEBE_SYN), "abertura simultânea não é suportada");
        assertThrows(IllegalStateException.class, () -> em(LISTEN, new Relogio()).tratar(RECEBE_ACK));
        assertThrows(IllegalStateException.class, () -> em(LISTEN, new Relogio()).tratar(RECEBE_RST));
    }

    // ---------- a tabela completa: 11 estados x 10 eventos ----------

    @Test void tabelaCompletaDeTransicoes() {
        Map<Solution.Estado, Map<Solution.Evento, Solution.Estado>> esperado = new EnumMap<>(Solution.Estado.class);
        for (Solution.Estado e : Solution.Estado.values()) esperado.put(e, new EnumMap<>(Solution.Evento.class));
        Object[][] regras = {
            {CLOSED, ABERTURA_PASSIVA, LISTEN}, {CLOSED, ABERTURA_ATIVA, SYN_SENT},
            {LISTEN, RECEBE_SYN, SYN_RCVD}, {LISTEN, FECHAR, CLOSED},
            {SYN_SENT, RECEBE_SYN_ACK, ESTABLISHED}, {SYN_SENT, FECHAR, CLOSED}, {SYN_SENT, RECEBE_RST, CLOSED}, {SYN_SENT, TIMEOUT_CONEXAO, CLOSED},
            {SYN_RCVD, RECEBE_ACK, ESTABLISHED}, {SYN_RCVD, FECHAR, FIN_WAIT_1}, {SYN_RCVD, RECEBE_RST, LISTEN}, {SYN_RCVD, TIMEOUT_CONEXAO, LISTEN},
            {ESTABLISHED, FECHAR, FIN_WAIT_1}, {ESTABLISHED, RECEBE_FIN, CLOSE_WAIT}, {ESTABLISHED, RECEBE_RST, CLOSED},
            {FIN_WAIT_1, RECEBE_ACK, FIN_WAIT_2}, {FIN_WAIT_1, RECEBE_FIN, CLOSING}, {FIN_WAIT_1, RECEBE_FIN_ACK, TIME_WAIT}, {FIN_WAIT_1, RECEBE_RST, CLOSED},
            {FIN_WAIT_2, RECEBE_FIN, TIME_WAIT}, {FIN_WAIT_2, RECEBE_RST, CLOSED},
            {CLOSE_WAIT, FECHAR, LAST_ACK}, {CLOSE_WAIT, RECEBE_RST, CLOSED},
            {CLOSING, RECEBE_ACK, TIME_WAIT}, {CLOSING, RECEBE_RST, CLOSED},
            {LAST_ACK, RECEBE_ACK, CLOSED}, {LAST_ACK, RECEBE_RST, CLOSED},
            {TIME_WAIT, RECEBE_FIN, TIME_WAIT}, {TIME_WAIT, RECEBE_RST, TIME_WAIT},
        };
        for (Object[] r : regras) esperado.get((Solution.Estado) r[0]).put((Solution.Evento) r[1], (Solution.Estado) r[2]);

        int validas = 0;
        for (Solution.Estado origem : Solution.Estado.values()) {
            for (Solution.Evento evento : Solution.Evento.values()) {
                Solution.ConexaoTcp c = em(origem, new Relogio());
                Solution.Estado destino = esperado.get(origem).get(evento);
                String par = origem + " + " + evento;
                if (destino == null) {
                    assertFalse(c.aceita(evento), par);
                    assertThrows(IllegalStateException.class, () -> c.tratar(evento), par);
                    assertEquals(origem, c.estado(), par + ": o estado não pode mudar");
                } else {
                    validas++;
                    assertTrue(c.aceita(evento), par);
                    assertEquals(destino, c.tratar(evento), par);
                }
            }
        }
        assertEquals(regras.length, validas);
    }

    // ---------- validações ----------

    @Test void argumentosInvalidos() {
        assertThrows(IllegalArgumentException.class, () -> new Solution.ConexaoTcp(0, new Relogio()));
        assertThrows(IllegalArgumentException.class, () -> new Solution.ConexaoTcp(-5, new Relogio()));
        assertThrows(IllegalArgumentException.class, () -> new Solution.ConexaoTcp(30_000, null));
        Solution.ConexaoTcp c = nova(new Relogio());
        assertThrows(IllegalArgumentException.class, () -> c.tratar(null));
        assertThrows(IllegalArgumentException.class, () -> c.aceita(null));
    }
}
